import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';

export default class AccountQuickLinks extends NavigationMixin {
    @api recordId;
    casesUrl = null;

    connectedCallback() {
        const caseListPageRef = {
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Case',
                actionName: 'list',
                state: {
                    filterName: 'My_Open_Cases'
                }
            }
        };

        NavigationMixin.GenerateUrl(caseListPageRef)
            .then((url) => {
                this.casesUrl = url;
            })
            .catch(() => {
                this.casesUrl = null;
            });
    }

    handleAction(event) {
        const action = event.currentTarget.dataset.action;

        if (!this.recordId) {
            return;
        }

        if (action === 'new-contact') {
            this.openNewContact();
        } else if (action === 'contacts') {
            this.openContacts();
        } else if (action === 'edit') {
            this.openEdit();
        }
    }

    openNewContact() {
        const pageRef = {
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Contact',
                actionName: 'new',
                state: {
                    defaultFieldValues: encodeDefaultFieldValues({
                        AccountId: this.recordId
                    })
                }
            }
        };

        this[NavigationMixin.Navigate](pageRef);
    }

    openContacts() {
        const pageRef = {
            type: 'standard__relatedList',
            attributes: {
                objectApiName: 'Account',
                relatedListId: 'Contacts',
                recordIds: [this.recordId]
            }
        };

        this[NavigationMixin.Navigate](pageRef);
    }

    openEdit() {
        const pageRef = {
            type: 'standard__recordPage',
            attributes: {
                apiName: 'Account',
                actionName: 'edit',
                recordId: this.recordId
            }
        };

        this[NavigationMixin.Navigate](pageRef);
    }
}
