import { LightningElement, track } from 'lightning/webcomponent';
import { searchContacts } from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    @track searchResults = [];
    @track error = '';
    searchTerm = '';

    #timeoutId = null;
    #requestId = 0;
    #isDisconnected = false;

    handleSearch(event) {
        const value = event.target.value || '';
        this.searchTerm = value;

        if (this.#timeoutId !== null) {
            clearTimeout(this.#timeoutId);
            this.#timeoutId = null;
        }

        const trimmed = value.trim();

        if (trimmed.length < 2) {
            this.#requestId += 1;
            this.searchResults = [];
            this.error = '';
            return;
        }

        this.error = '';
        this.#requestId += 1;
        this.#timeoutId = setTimeout(() => {
            this.#timeoutId = null;

            if (this.#isDisconnected) {
                return;
            }

            const latestTerm = (this.searchTerm || '').trim();
            if (latestTerm.length < 2) {
                this.#requestId += 1;
                this.searchResults = [];
                this.error = '';
                return;
            }

            const requestId = this.#requestId;
            searchContacts({ searchTerm: latestTerm })
                .then((contacts) => {
                    if (this.#isDisconnected || requestId !== this.#requestId) {
                        return;
                    }
                    this.searchResults = contacts || [];
                    this.error = '';
                })
                .catch((error) => {
                    if (this.#isDisconnected || requestId !== this.#requestId) {
                        return;
                    }
                    this.searchResults = [];
                    this.error = (error && error.body && error.body.message) || 'Unexpected error';
                });
        }, 300);
    }

    disconnectedCallback() {
        this.#isDisconnected = true;
        if (this.#timeoutId !== null) {
            clearTimeout(this.#timeoutId);
            this.#timeoutId = null;
        }
        this.#requestId += 1;
    }
}
