import { LightningElement, wire, track } from 'lwc';
import { subscribe, unsubscribe, publish, APPLICATION_SCOPE } from 'lightning/messageService';
import { MessageContext } from 'lightning/messageContext';
import { Account_Selected__c } from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    @track selectedRecordId;
    subscriptionId;

    @wire(MessageContext)
    setMessageContext(messageContext) {
        this.messageContext = messageContext;
        if (this.isConnected) {
            this.subscribeToChannel();
        }
    }

    connectedCallback() {
        this.subscribeToChannel();
    }

    disconnectedCallback() {
        this.unsubscribeFromChannel();
    }

    handleClear() {
        if (this.messageContext) {
            publish(this.messageContext, Account_Selected__c, { recordId: null }, { scope: APPLICATION_SCOPE });
        }
    }

    handleMessage(message) {
        this.selectedRecordId = (message && message.recordId) ? message.recordId : null;
    }

    subscribeToChannel() {
        if (this.messageContext && !this.subscriptionId) {
            this.subscriptionId = subscribe(
                this.messageContext,
                Account_Selected__c,
                (message) => this.handleMessage(message),
                { scope: APPLICATION_SCOPE }
            );
        }
    }

    unsubscribeFromChannel() {
        if (this.subscriptionId) {
            unsubscribe(this.subscriptionId);
            this.subscriptionId = undefined;
        }
    }
