import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import LightningConfirm from 'lightning/confirm';
import { deleteRecord } from 'lightning/uiRecordApi';
import ShowToastEvent from 'lightning/platformShowToastEvent';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    @api opportunities = [];

    columns = [
        { label: 'Name', fieldName: 'Name' },
        { label: 'Stage', fieldName: 'StageName' },
        { label: 'Amount', fieldName: 'Amount', type: 'currency' },
        {
            type: 'action',
            typeAttributes: {
                rowActions: [
                    { label: 'View', name: 'view' },
                    { label: 'Edit', name: 'edit' },
                    { label: 'Delete', name: 'delete' }
                ]
            }
        }
    ];

    handleRowAction(event) {
        const action = event.detail.action;
        const row = event.detail.row;

        switch (action.name) {
            case 'view':
                this.navigateToRecordPage(row.Id, 'view');
                break;
            case 'edit':
                this.navigateToRecordPage(row.Id, 'edit');
                break;
            case 'delete':
                this.handleDelete(row);
                break;
        }
    }

    navigateToRecordPage(recordId, actionName) {
        const pageReference = {
            type: 'standard__recordPage',
            attributes: {
                recordId,
                actionName
            }
        };

        this[NavigationMixin.Navigate](pageReference);
    }

    handleDelete(row) {
        LightningConfirm.open({
            label: 'Confirm',
            message: `Are you sure you want to delete ${row.Name}?`,
            confirmText: 'Delete',
            cancelText: 'Cancel'
        }).then((response) => {
            if (response === 'confirm') {
                deleteRecord(row.Id)
                    .then(() => {
                        this.opportunities = this.opportunities.filter(
                            (opportunity) => opportunity.Id !== row.Id
                        );

                        this.dispatchEvent(
                            new ShowToastEvent({
                                title: 'Opportunity deleted',
                                message: 'Opportunity deleted.',
                                variant: 'success'
                            })
                        );
                    })
                    .catch((error) => {
                        const message =
                            error.body && error.body.message
                                ? error.body.message
                                : error.message;

                        this.dispatchEvent(
                            new ShowToastEvent({
                                title: 'Delete failed',
                                message,
                                variant: 'error'
                            })
                        );
                    });
            }
        });
    }
}
