import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    stats = null;
    error = null;

    _isConnected = false;
    _inFlight = false;
    _timerId = null;
    _visibilityHandler = null;

    connectedCallback() {
        if (this._isConnected) {
            return;
        }

        this._isConnected = true;
        this._visibilityHandler = () => this._handleVisibilityChange();
        document.addEventListener('visibilitychange', this._visibilityHandler);

        if (document.visibilityState === 'visible') {
            this._loadAndSchedule();
        }
    }

    disconnectedCallback() {
        this._isConnected = false;
        this._clearTimer();

        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = null;
        }
    }

    get waiting() {
        return this.stats ? this.stats.waiting : '';
    }

    get longestWaitMinutes() {
        return this.stats ? this.stats.longestWaitMinutes : '';
    }

    _loadAndSchedule() {
        this._clearTimer();
        this._poll();
        this._scheduleNext();
    }

    _poll() {
        if (!this._isConnected || document.visibilityState === 'hidden' || this._inFlight) {
            return;
        }

        this._inFlight = true;

        getQueueStats()
            .then((stats) => {
                if (this._isConnected) {
                    this.stats = stats;
                    this.error = null;
                }
            })
            .catch((error) => {
                if (this._isConnected) {
                    this.error = error?.body?.message ?? error?.message ?? 'Error loading queue stats.';
                }
            })
            .finally(() => {
                this._inFlight = false;
            });
    }

    _scheduleNext() {
        if (!this._isConnected) {
            return;
        }

        this._timerId = setTimeout(() => {
            if (!this._isConnected || document.visibilityState === 'hidden') {
                return;
            }

            this._poll();
            this._scheduleNext();
        }, 60000);
    }

    _clearTimer() {
        if (this._timerId !== null) {
            clearTimeout(this._timerId);
