import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target?.dataset?.field ?? event.currentTarget?.dataset?.field;
        const value = event.detail.value ?? '';

        if (field === 'fullName') {
            this.fullName = value;
        } else if (field === 'email') {
            this.email = value;
        } else if (field === 'company') {
            this.company = value;
        }
    }

    handleRegister() {
        const fullNameInput = this.template.querySelector('[data-field="fullName"]');
        const emailInput = this.template.querySelector('[data-field="email"]');
        const companyInput = this.template.querySelector('[data-field="company"]');

        if (!fullNameInput || !emailInput || !companyInput) {
            return;
        }

        const emailValue = (this.email || '').trim();
        const domain = emailValue.split('@').pop().trim().toLowerCase();
        const personalDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

        if (personalDomains.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        let isValid = true;
        this.template.querySelectorAll('lightning-input').forEach((input) => {
            input.reportValidity();
            if (!input.checkValidity()) {
                isValid = false;
            }
        });

        if (!isValid) {
            return;
        }

        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                const toastEvent = new ShowToastEvent({
                    title: 'Registered',
                    message: '',
                    variant: 'success'
                });
                this.dispatchEvent(toastEvent);
            })
            .catch((error) => {
                const toastEvent = new ShowToastEvent({
                    title: 'Registration failed',
                    message: error?.body?.message ?? 'Registration failed',
                    variant: 'error'
                });
                this.dispatchEvent(toastEvent);
            });
    }
}
