import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    _tasks = [];
    nextId = 1;
    newLabel = '';

    @api
    get tasks() {
        return this._tasks.map((task) => ({ ...task }));
    }

    set tasks(value) {
        this._tasks = this.copyTasks(value);
    }

    get headingText() {
        return String(this.heading == null ? '' : this.heading).toUpperCase();
    }

    get items() {
        return this._tasks;
    }

    get remaining() {
        return this._tasks.filter((task) => !task.done).length;
    }

    copyTasks(value) {
        if (!Array.isArray(value)) {
            return [];
        }

        return value.map((task) => ({
            id: task ? task.id : undefined,
            label: task && task.label != null ? task.label : '',
            done: !!(task && task.done)
        }));
    }

    nextTaskId() {
        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (this._tasks.some((task) => String(task.id) === id));
        return id;
    }

    handleLabelChange(event) {
        const value = event && event.detail ? event.detail.value : undefined;
        this.newLabel = String(value == null ? '' : value);
    }

    handleAdd() {
        const input = this.template.querySelector('.new-task');
        const rawValue = input ? input.value : this.newLabel;
        const label = String(rawValue == null ? '' : rawValue).trim();

        if (!label) {
            return;
        }

        this._tasks = [
            ...this._tasks,
            {
                id: this.nextTaskId(),
                label,
                done: false
            }
        ];

        this.newLabel = '';
        if (input) {
            input.value = '';
        }

        this.dispatchEvent(
            new CustomEvent('taskadded', {
                bubbles: true,
                composed: true,
                detail: { label }
            })
        );
    }

    handleToggle(event) {
        const rawId =
            event && event.target && event.target.dataset
                ? event.target.dataset.id
                : undefined;

        if (rawId === undefined || rawId === null) {
            return;
        }

        const id = String(rawId);
        this._tasks = this._tasks.map((task) =>
            String(task.id) === id ? { ...task, done: !task.done } : task
        );
    }
}
